/**
 * Web client entry: the plugin detail page's settings card.
 *
 * Contract: this bundle is consumed through the client module table (esbuild
 * CJS output wrapped by the build script in window.__ModuleLoader__.load),
 * `exports.inject` names the Cordis client services, and `exports.apply(ctx)`
 * registers everything inside ctx.effect-managed lifecycles.
 *
 * The card occupies the keyed slot `plugins.bundle.config` for this bundle and
 * renders through the engine's `PluginConfigViewProps`. The Plugins page passes
 * a ready `form` only to its item and row cards; a bundle entry's card receives
 * `form` absent, so this entry fetches its own live handle for the settings
 * namespace through the `configForms` service and subscribes to it (the page
 * face stays preferred for engines that do hand one over). The card stages
 * edits locally and submits them as one `{ op: 'set' | 'unset', path: [field] }`
 * batch fenced by the revision it read. A field is overridden exactly when its
 * key is present in `state.user`.
 *
 * Styling: the engines publish no settings-form component this plugin may
 * depend on (QiLin's primitives retired them; DSH's are gone there), so the
 * card carries its own stylesheet. Every rule mirrors the host settings form's
 * own CSS — same metrics, same `--dsw-alias-*` / `--dsw-radius-*` tokens with
 * literal fallbacks — under this plugin's `km-` prefix, and is injected once
 * into the document the card renders in. That is what makes the card read as
 * one of the host's settings pages in both color schemes; see `CARD_CSS`.
 */

export const inject = ["slots", "locale", "configForms"] as const;

// Resolved through the shell's module table at runtime (factory require).
import { useEffect, useState } from "react";

/** Settings namespace served by the host for this plugin's config schema. */
const SETTINGS_NS = "dsh-kylin-memory";
/** Dictionary namespace owned by this client plugin. */
const LOCALE_NS = "kylinMemory.settings";
/** `id` of the one stylesheet element this entry owns per document. */
const STYLE_ID = "dsh-kylin-memory-settings-styles";

interface Translate {
  (key: string): string;
}

/** One atomic write the page's `mutate` accepts. */
type PathOp =
  | { op: "set"; path: string[]; value: number }
  | { op: "unset"; path: string[] };

/** Sync state of the plugin's settings namespace, as the page publishes it. */
interface ConfigFormSnapshot {
  status: "loading" | "ready" | "unavailable";
  value: Record<string, unknown> | undefined;
  user: unknown;
  revision: number | undefined;
  writable: boolean;
}

/**
 * The settings service's live form handle for one namespace. The Plugins page
 * passes a ready `{ state, mutate }` face to `plugins.item` and row cards, but
 * renders `plugins.bundle.config` entries with `form` absent (verified against
 * the engine's built bundle), so this entry fetches its own handle through the
 * `configForms` service and subscribes for reactivity.
 */
interface ConfigFormHandle {
  getSnapshot(): ConfigFormSnapshot;
  subscribe(listener: () => void): () => void;
  mutate(ops: readonly PathOp[], expectedRevision?: number): Promise<boolean>;
}

/** The page-owned form for this entry. */
interface ConfigPageForm {
  state: ConfigFormSnapshot;
  mutate(ops: readonly PathOp[], expectedRevision?: number): Promise<boolean>;
}

/** Props the `plugins.bundle.config` seat supplies. */
interface PluginConfigViewProps {
  view: "summary" | "page";
  form?: ConfigPageForm | undefined;
}

/** Minimal shape of the client plugin context this entry composes against. */
interface ClientContext {
  slots: {
    inject(name: string, register: () => unknown): unknown;
    register(options: Record<string, unknown>, component: unknown): unknown;
  };
  locale: {
    bind(ns: string): Translate;
    register(ns: string, dictionaries: Record<string, Record<string, string>>): unknown;
  };
  configForms: {
    get(entryId: string): ConfigFormHandle;
  };
  effect(register: () => unknown, label?: string): unknown;
}

