/**
 * Put this card's stylesheet in the document once.
 *
 * Idempotent per document (the Plugins page may mount the entry more than once
 * across engine restarts); the returned disposer removes only the element this
 * call created, and a second caller that found an existing sheet disposes
 * nothing.
 *
 * @returns disposer removing the stylesheet this call appended.
 */
export function installStyles(): () => void {
  if (typeof document === "undefined") return () => {};
  if (document.getElementById(STYLE_ID) !== null) return () => {};
  const style = document.createElement("style");
  style.id = STYLE_ID;
  style.textContent = CARD_CSS;
  document.head.appendChild(style);
  return () => { style.remove(); };
}

/** The section fields this card edits, in display order. */
const FIELDS = [
  "freshTurnCount",
  "archiveThresholdTokens",
  "maintenanceInterval",
  "recallMaxNodes",
  "semanticScoreThreshold",
] as const;

type FieldName = (typeof FIELDS)[number];

/** Each field's label and hint dictionary keys plus its keypad hint. */
const FIELD_COPY: Record<FieldName, { label: string; hint: string; mode: "numeric" | "decimal" }> = {
  freshTurnCount: { label: "freshTurnCount", hint: "freshTurnCountHint", mode: "numeric" },
  archiveThresholdTokens: { label: "archiveThresholdTokens", hint: "archiveThresholdTokensHint", mode: "numeric" },
  maintenanceInterval: { label: "maintenanceInterval", hint: "maintenanceIntervalHint", mode: "numeric" },
  recallMaxNodes: { label: "recallMaxNodes", hint: "recallMaxNodesHint", mode: "numeric" },
  semanticScoreThreshold: { label: "semanticScoreThreshold", hint: "semanticScoreThresholdHint", mode: "decimal" },
};

/** Whether the user layer carries this field (presence marks an override, not its value). */
function isOverridden(user: unknown, field: FieldName): boolean {
  return typeof user === "object" && user !== null && Object.prototype.hasOwnProperty.call(user, field);
}

/** Read one accepted field as the text an input shows. */
function acceptedText(value: Record<string, unknown> | undefined, field: FieldName): string {
  const raw = value?.[field];
  return typeof raw === "number" || typeof raw === "string" ? String(raw) : "";
}

/** Whether one staged edit is a number or blank. */
function isValid(text: string): boolean {
  return text.trim() === "" || Number.isFinite(Number(text));
}

/** One labelled numeric row with its override state and reset control. */
function ConfigField(props: {
  field: FieldName;
  label: string;
  hint: string;
  mode: "numeric" | "decimal";
  text: string;
  invalid: boolean;
  overridden: boolean;
  disabled: boolean;
  t: Translate;
  onChange(text: string): void;
  onReset(): void;
}) {
  const id = `plugin-config-kylin-memory-${props.field}`;
  const messageId = `${id}-message`;
  return (
    <div className="km-field" data-config-field={props.field}>
      <div className="km-head">
        <label className="km-label" htmlFor={id}>{props.label}</label>
        {props.overridden ? (
          <span className="km-badges">
            <span className="km-tag">{props.t("overridden")}</span>
            <button type="button" className="km-reset" disabled={props.disabled} onClick={props.onReset}>
              {props.t("reset")}
            </button>
          </span>
        ) : null}
      </div>
      <input
        id={id}
        className="km-input"
        type="text"
        inputMode={props.mode}
        autoComplete="off"
        aria-invalid={props.invalid || undefined}
        aria-describedby={messageId}
        disabled={props.disabled}
        value={props.text}
        onChange={(event) => { props.onChange(event.target.value); }}
      />
      <p id={messageId} className={props.invalid ? "km-invalid" : "km-hint"}>
        {props.invalid ? props.t("invalidNumber") : props.hint}
      </p>
    </div>
  );
}

/**
 * Render the bundle's settings card for the plugin detail page.
 *
 * The form arrives through one of two faces: the page supplies a ready
 * `{ state, mutate }` snapshot for entries it serves a form to, and this
 * entry additionally fetches its own live handle from the `configForms`
 * service (`self`), because the Plugins page renders `plugins.bundle.config`
 * entries without a `form` prop. The card prefers the page face, falls back
 * to the self handle, and subscribes to keep the snapshot current.
 */
export function KylinMemoryConfigCard(props: PluginConfigViewProps & { t: Translate; self?: ConfigFormHandle }) {
  const live = props.self;
  const [snapshot, setSnapshot] = useState<ConfigFormSnapshot | undefined>(() => live?.getSnapshot());
  useEffect(() => {
    if (live === undefined) return;
    setSnapshot(live.getSnapshot());
    return live.subscribe(() => { setSnapshot(live.getSnapshot()); });
  }, [live]);
  const form: ConfigPageForm | undefined = props.form ?? (snapshot === undefined || live === undefined
    ? undefined
    : { state: snapshot, mutate: (ops, expectedRevision) => live.mutate(ops, expectedRevision) });
  const [staged, setStaged] = useState<Record<string, string>>({});
  const [saving, setSaving] = useState(false);
  const [failed, setFailed] = useState(false);
  const t = props.t;

  // The summary seat stays empty: the page draws the title and one-liner itself.
  if (props.view === "summary") return null;
  if (form === undefined) {
    return <p className="km-notice" role="status">{t(snapshot?.status === "unavailable" ? "unavailable" : "loading")}</p>;
  }
  if (form.state.status === "unavailable") {
    return <p className="km-notice" role="status">{t("unavailable")}</p>;
  }
  if (form.state.status === "loading") {
    return <p className="km-notice" role="status">{t("loading")}</p>;
  }

  const state = form.state;
  const textOf = (field: FieldName): string => staged[field] ?? acceptedText(state.value, field);
  const changed = FIELDS.filter((field) => textOf(field) !== acceptedText(state.value, field));
  const invalid = FIELDS.some((field) => !isValid(textOf(field)));
  const dirty = changed.length > 0;
  const disabled = !state.writable || saving;

  const save = (): void => {
    const ops: PathOp[] = changed.map((field) => {
      const text = textOf(field).trim();
      return text === ""
        ? { op: "unset", path: [field] }
        : { op: "set", path: [field], value: Number(text) };
    });
    if (ops.length === 0) return;
    setSaving(true);
    setFailed(false);
    void form.mutate(ops, state.revision)
      .then((accepted) => {
        if (accepted) setStaged({});
        else setFailed(true);
      }, () => { setFailed(true); })
      .finally(() => { setSaving(false); });
  };

  const reset = (field: FieldName): void => {
    setSaving(true);
    setFailed(false);
    void form.mutate([{ op: "unset", path: [field] }], state.revision)
      .then((accepted) => {
        if (accepted) setStaged((current) => { const next = { ...current }; delete next[field]; return next; });
        else setFailed(true);
      }, () => { setFailed(true); })
      .finally(() => { setSaving(false); });
  };

  return (
    <div className="km-form" data-config-namespace={SETTINGS_NS}>
      {!state.writable ? <p className="km-notice" role="status">{t("readOnly")}</p> : null}
      {FIELDS.map((field) => (
        <ConfigField
          key={field}
          field={field}
          label={t(FIELD_COPY[field].label)}
          hint={t(FIELD_COPY[field].hint)}
          mode={FIELD_COPY[field].mode}
          text={textOf(field)}
          invalid={!isValid(textOf(field))}
          overridden={isOverridden(state.user, field)}
          disabled={disabled}
          t={t}
          onChange={(text) => { setStaged((current) => ({ ...current, [field]: text })); }}
          onReset={() => { reset(field); }}
        />
      ))}
      <div className="km-footer">
        {failed ? <p className="km-failed" role="status">{t("saveFailed")}</p> : null}
        <button
          type="button"
          className="km-save"
          disabled={!dirty || invalid || disabled}
          onClick={save}
        >
          {t(saving ? "saving" : "save")}
        </button>
      </div>
    </div>
  );
}

/** Mount the bundle's settings card on the plugin detail page. */
export function apply(ctx: ClientContext): void {
  // The Plugins page renders `plugins.bundle.config` entries without a form,
  // so the card sources its state from the settings service's own handle for
  // this namespace (same describe mirror the page's row forms read).
  const selfForm = ctx.configForms.get(SETTINGS_NS);
  ctx.effect(() => installStyles(), "kylin-memory: settings styles");
  ctx.effect(
    () => ctx.locale.register(LOCALE_NS, { zh, en }),
    "kylin-memory: dictionaries",
  );
  ctx.effect(
    () => ctx.slots.inject("plugins.bundle.config", () => ctx.slots.register({
      name: "plugins.bundle.config",
      key: SETTINGS_NS,
      locale: LOCALE_NS,
      inject: () => ({ self: selfForm }),
    }, KylinMemoryConfigCard)),
    "kylin-memory: settings page",
  );
}
